  "plans.mobilePriceNote": "手機專用計劃喺美國定價係每月 $4.99。App Store 或者 Google Play 會喺購買之前顯示實際本地訂閱價錢同任何適用稅項。佢嘅產品、地點同員工限額會喺推出嗰陣另外設定，同網站級別分開。",
