  "exports.eyebrow": "資料",
  "exports.title": "匯出與備份",
  "exports.subtitleStart": "下載一律只限",
  "exports.subtitleRest": "。每個檔案都會標明公司名稱同製作日期。",
  "exports.createBusinessFirst": "請先建立一間公司 — 匯出屬於公司，唔屬於呢個應用程式。",
  "exports.lockedTitle": "CSV 同 Excel 匯出係 Business 功能",
  "exports.lockedDesc": "你嘅工作區而家用緊 Essentials 計劃。Business 包括 CSV 同 Excel 匯出、存貨估值、無限產品同員工、供應商、採購同套裝。",
  "exports.seeBusiness": "睇吓 Business 包括啲咩",
  "exports.whatTheseAre": "呢啲檔案係乜嘢",
  "exports.about1": "每個資料集都有 CSV 或者真正嘅 Excel 工作簿 (.xlsx) — 完整存貨工作簿只限 Excel，每個資料集佔一頁。CSV 檔案可以用 Excel、Numbers、Google Sheets 同大部份存貨應用程式打開。UTF-8 文字、加引號嘅逗號、備註入面嘅換行同編碼開頭嘅零都會保留，開頭似公式嘅儲存格亦會被中和，令試算表將佢哋當作文字打開。",
  "exports.about2": "喺 Excel 檔案入面，SKU、UPC、ISBN 同條碼都係文字儲存格 — 永遠唔會變成科學記數法，亦唔會刪走開頭嘅零 — 欄闊、標題篩選同貨幣或數量格式都已經設定好。完整存貨工作簿會將產品、存貨量、地點同出入記錄分開唔同工作表。",
  "exports.about3": "非常大嘅匯出每個資料集最多停喺 20,000 行 — 如果發生咁嘅情況，檔案名會講明（truncated-20000），所以唔完整嘅檔案永遠唔會被當成完整。",
  "exports.about4": "備份係你資料嘅快照，唔係一鍵還原。還原係人手做、要先檢查嘅工作，所以請好好保存呢個檔案 — 應用程式入面暫時冇嘢可以憑佢重建一間已刪除嘅公司。應用程式程式碼同 Base44 平台備份係另外處理，唔包括喺呢啲檔案入面。",
  "exports.about5": "相片同附件只會列出佢哋嘅儲存連結 — 圖片檔案本身唔會包喺下載入面。",
  "exports.backupTitle": "完整備份",
  "exports.backupDesc": "一個檔案包含呢間公司嘅產品、地點、存貨量、完整出入記錄、供應商、採購、訂單、退貨、盤點同上架 — 仲有佢嘅個人檔案設定。請放喺一個你控制到嘅地方。",
