  "print.pickReturnHint": "請由清單揀一個已記錄嘅退貨嚟預覽文件。",
  "print.chooseStyleHint": "請先揀一個樣式，再由清單揀產品。預覽會準確顯示打印機印出嚟嘅嘢。",
  "print.howToReach": "點樣連接你嘅打印機",
  "print.howIntro": "呢個應用程式會連接你已經擁有嘅打印機 — 佢本身唔係一部打印機。連接有四種方法，標籤喺兩個計劃、任何一種連接方式都印得。裝箱單、採購單、供應商文件同報告係 Business 專用，無論用邊種連接都一樣。",
  "print.howBluetoothLead": "Bluetooth。",
  "print.howBluetoothBody": "喺呢一頁，喺桌面版 Chrome 或 Edge 同 Android Chrome 上面：揀你嘅標籤打印機，標籤就會直接傳過去。iOS Safari 唔得 — 喺 iPhone 上面，Bluetooth 列印係跟手機應用程式。只識 Zebra ZPL 或者 Brother 專用語言嘅打印機，係唔會明白呢一頁傳送嘅標籤；喺話佢得之前，會先用真打印機檢查過。",
  "print.howWifiLead": "Wi-Fi。",
  "print.howWifiBody": "將打印機安裝喺你店舖嘅 Wi-Fi 上面，然後用「列印」按鈕 — 佢會透過呢部電腦上面安裝咗嘅打印機，經店舖網絡列印。喺 iPhone 上面，AirPrint 係內置嘅：同一 Wi-Fi 上面嘅 AirPrint 打印機就會喺列印選單出現，唔使線，唔使應用程式，應用程式亦唔需要任何 AirPrint 專用程式碼。打印機必須支援 AirPrint（大部份新機都支援），電話同打印機必須喺同一個 Wi-Fi。",
  "print.howEthernetLead": "Ethernet。",
  "print.howEthernetBody": "用 Ethernet 線將打印機接去店舖網絡，喺電腦上面安裝，然後用「列印」按鈕列印。Ethernet 係桌面同電腦嘅路徑 — iPhone 唔用 Ethernet 線。",
  "print.howUsbLead": "USB。",
  "print.howUsbBody": "用線將打印機插去電腦，再用「列印」按鈕 — 佢會透過嗰度安裝咗嘅打印機列印。喺用 USB OTG 線嘅 Android 電話上面，上面嘅 USB 按鈕會直接同打印機溝通。iPhone 唔可以直接用 USB 列印 — 嗰度冇 WebUSB — 所以請用 Wi-Fi / AirPrint，或者手機應用程式嘅 Bluetooth。",
  "print.howCordsLead": "線仍然幫到 iPhone，只係多一個步驟。",
  "print.howCordsBody": "插咗去店舖電腦嘅 USB 打印機，或者接咗去網絡嘅 Ethernet 打印機，會透過店舖 Wi-Fi（AirPrint / 共享打印機）喺你嘅 iPhone 上面出現 — 線將打印機穩穩噉放上網絡，電話就無線連接到佢。",
  "print.howOfflineLead": "如果斷咗網，",
  "print.howOfflineBody": "呢一頁上面已經有嘅標籤同文件仍然印得 — 「列印」按鈕、標籤 PDF、Bluetooth 同 USB 都唔需要連線。需要上網嘅，係一開始載入呢一頁同佢嘅產品。完全離線模式（完全唔上網都喺應用程式入面工作）係另外一個更大嘅工程，呢度唔會話有。",
  "print.templatePrice": "價錢牌",
