  "settings.cancelTerms.graceTitle": "付費期結束之後 — 15 日寬限期，然後刪除：",
  "settings.cancelTerms.intro": "呢啲係 Luminous StockHaven 付費訂閱嘅條款。網站訂閱嘅賬單係經 Stripe 處理。你可以隨時用下面嘅「取消訂閱」按鈕自己取消訂閱 — 唔需要職員批准。取消同退款要求亦都可以透過官方客服聯絡方式 theluminousbookshop@outlook.com 處理。",
  "settings.cancelTerms.noApprovalBody": "你可以隨時自己取消訂閱。唔需要職員批准。之後嘅續費要等賬單供應商確認取消之後先會停止。",
  "settings.cancelTerms.noApprovalTitle": "唔使批准都可以取消：",
  "settings.cancelTerms.paymentBody": "付費試用方面，七日試用喺登記嗰陣要提供付款方式。除非喺適用嘅試用取消期限之前取消，否則試用完咗之後會自動收取所選月費計劃嘅費用。價錢、首次收費日期同供應商指定嘅取消期限，一定要喺登記嗰陣顯示出嚟。試用嘅賬單係經 Stripe 處理。",
  "settings.cancelTerms.paymentTitle": "付款方式同自動續費：",
  "settings.cancelTerms.remainingBody": "如果你已經為某個賬單期付咗費，你可以繼續用到已核實嘅付費到期日為止。想提早終止，就要得到供應商適當嘅確認，同埋處理任何適用嘅退款。免費試用嘅使用權會按供應商確認嘅試用終止日期結束。",
  "settings.cancelTerms.remainingTitle": "剩餘使用權：",
  "settings.cancelTerms.storesBody": "如果你曾經透過 Google Play 或者 Apple App Store 訂閱，你嘅訂閱係由嗰間商店收費同管理。你可能要直接喺用嚟訂閱嘅同一個 Google 或者 Apple 賬戶入面嘅訂閱部分取消。取消另一份網站訂閱、解除安裝呢個 app，或者要求刪除 Luminous StockHaven 賬戶，唔會自動取消經商店收費嘅訂閱。請睇返你嘅購買收據，確認係邊個向你收費。",
  "settings.cancelTerms.storesTitle": "Google Play 同 Apple App Store 訂閱（如果你曾經透過商店訂閱）：",
  "settings.cancelTerms.title": "取消條款及細則",
  "settings.cancelTerms.trialBody": "七日試用每位合資格客戶只可以用一次。取消試用或者訂閱唔會再畀多一次試用；返嚟嘅客戶要揀付費訂閱。",
