  "staff.access.noSeatBody": "你嘅賬戶喺呢間商戶冇員工席位，所以佢嘅庫存唔會開放畀你。請叫擁有人喺「員工同角色」入面加返你。",
  "staff.access.noSeatTitle": "呢間商戶未開放畀你呢個登入",
  "staff.access.pendingBody": "呢間商戶有一個寄去你電郵嘅邀請，仲未啟用。請叫擁有人將你嘅員工狀態設為生效。喺嗰之前，呢度咩都睇唔到。",
  "staff.access.pendingTitle": "你嘅邀請仲未生效",
  "staff.access.signOut": "登出",
  "staff.access.suspendedBody": "管理員已經暫停咗呢個員工賬戶喺生效商戶嘅使用權。請叫佢哋將你設返做生效，然後再登入。",
  "staff.access.suspendedTitle": "你嘅使用權已暫停",
  "staff.addFirst": "新增第一位員工",
  "staff.addMember": "新增員工",
  "staff.emptyBody": "加一個人，畀佢一個角色同相應嘅權限，佢就會收到電郵邀請，登入呢間商戶。",
  "staff.emptyTitle": "仲未有員工",
  "staff.eyebrow": "團隊",
  "staff.how.p1": "每位成員都有一個角色同自己嘅權限清單，所以你可以由一個角色開始，改一樣嘢，唔使開一個新角色。編輯角色唔會改寫已經用緊嗰個角色嘅成員 — 打開一位成員，先可以重新套用佢個角色嘅預設值。",
  "staff.how.p2": "自訂角色係 Business 計劃先有嘅功能：Essentials 計劃用五個內置角色（擁有人、經理、倉務員、銷售員、檢視者）。",
  "staff.how.p3": "邀請係用電郵寄出。成員接受咗先可以登入，喺呢個名單度移除一個人，唔會刪除佢嘅 app 賬戶。",
  "staff.how.p4": "分店係指派畀一個人嘅地點。會記錄喺佢張卡上面；佢可以打開啲咩，仍然由佢嘅角色同權限決定。",
  "staff.how.p5": "權限決定每個人可以打開啲咩：角色以外嘅選單項目會隱藏，被封鎖嘅頁面會顯示「唔係你角色範圍」嘅提示，而唔係嗰頁本身。改動會喺嗰個人下次載入 app 嗰陣生效；暫停一位成員會完全鎖住佢，入唔到。",
  "staff.how.p6": "管理員可以睇到同更改所有資料、管理 app 用戶同角色，永遠唔受員工角色限制。冇員工記錄嘅人 — 即係新商戶嘅擁有人 — 會保留完整使用權。",
  "staff.howTitle": "員工同角色係點運作",
