  "training.lessons.lost-email-recovery.step1": "唔要驚慌，亦唔要建立新帳號 — 新電郵會打開一個全新嘅、空嘅店面。你嘅商店仍喺你離開時嘅位置。",
  "training.lessons.lost-email-recovery.step2": "喺登入頁面上，撳「唔可以登入你嘅電郵嗎？」輸入你嘅帳號電郵，並使用一個備用密鑰：備用代碼，或傳送到你備用電郵嘅 6 位數字代碼。",
  "training.lessons.lost-email-recovery.step3": "呢只會打開一個步驟：更改你嘅帳號電郵。輸入你可以存取嘅電郵，並輸入傳送到該電郵嘅代碼。你嘅商店、庫存、團隊同歷史都會移至新電郵 — 冇任何遺失。",
  "training.lessons.lost-email-recovery.step4": "完成後，你又可以正常登入咗。請直接前往「設定 → 安全性同備用密鑰」，為新電郵設定新嘅備用密鑰。",
  "training.lessons.lost-email-recovery.title": "如果你入唔到你嘅電郵",
  "training.lessons.owner-staff-email-fix.step1": "如果團隊成員入唔到佢哋被新增時使用嘅電郵，佢哋可能根本唔需要你：佢哋自己嘅備用密鑰（備用代碼或備用電郵，位喺佢哋嘅「設定 → 安全性」）可以令佢哋從登入頁面自行更改帳號電郵。",
  "training.lessons.owner-staff-email-fix.step2": "如果佢哋從未設定備用密鑰，你可以為佢哋修正：打開「員工」，打開佢哋嘅記錄，並喺嗰度更改電郵。應用程式會將佢哋嘅整個世界一併移動 — 佢哋嘅帳號、佢哋喺你其他商店嘅資料列，同埋佢哋嘅試用歷史。",
  "training.lessons.owner-staff-email-fix.step3": "移動係刻意設計為全有或全無：佢哋永遠唔會同時以兩個電郵擁有存取權限，亦唔會建立重複帳號。佢哋目前嘅登入保持有效；通知會傳送到舊地址。",
  "training.lessons.owner-staff-email-fix.step4": "之後，請要求佢哋登入並設定備用密鑰（佢哋嘅培訓中有一課介紹呢一點），咁樣下次佢哋可以喺兩分鐘入面自行救援。",
  "training.lessons.owner-staff-email-fix.title": "當團隊成員被鎖喺外面時：修正佢哋嘅電郵",
  "training.lessons.spare-keys-setup.step1": "你嘅帳號隸屬喺你嘅電郵。如果你第日入唔到該電郵 — 被鎖定、更換服務商、任何原因 — 你嘅備用密鑰就係你返嚟嘅方法。請而家就設定好，趁一切仲運作正常時。",
  "training.lessons.spare-keys-setup.step2": "打開「設定」，搵到「安全性同備用密鑰」。揀「產生備用代碼」：你會睇到十個一次性代碼。佢哋只會顯示一次，因此請列印或寫落嚟，並保存在安全嘅地方。",
  "training.lessons.spare-keys-setup.step3": "喺同一個區段，新增一個備用電郵 — 你控制嘅第二個地址 — 並輸入我哋傳送到嗰度嘅 6 位數字代碼以驗證佢。任一備用密鑰都可以救援你；兩者都有最好。",
  "training.lessons.spare-keys-setup.step4": "絕唔要同任何人共用你嘅代碼，亦絕唔要喺本應用程式嘅恢復頁面以外嘅地方輸入佢哋。如果你嘅代碼唔足，請產生一組新代碼 — 舊代碼會停止運作。",
  "training.lessons.spare-keys-setup.title": "你嘅備用密鑰：請喺需要之前設定好",
  "purchasing.sendOrder": "傳送訂單",
  "purchasing.sendAgain": "再傳送",
  "purchasing.sentFlash": "訂單 {number} 已以電郵傳送至 {email}。",
  "purchasing.sentTo": "已傳送至 {email} · {date}",
  "purchasing.sendFailed": "唔可以傳送該訂單。",
  "training.lessons.mgr-send-supplier-order.step1": "訂單下達後，喺「採購」頁面上撳「傳送訂單」，佢會直接從應用程式入面傳送畀供應商。草稿唔可以傳送 — 請先下達訂單。",
  "training.lessons.mgr-send-supplier-order.step2": "供應商需要喺佢嘅「供應商」記錄上有電郵地址。如果缺少，應用程式會停止並通知你先新增 — 任何內容都絕唔會喺未真正傳送嘅情況下靜靜雞傳送或標示為已傳送。",
  "training.lessons.mgr-send-supplier-order.step3": "供應商會收到一封附有訂單 PDF 嘅電郵，只以本商店嘅名義傳送 — 電郵同文件只會顯示商戶嘅名稱，絕唔會顯示應用程式嘅名稱。",
  "training.lessons.mgr-send-supplier-order.step4": "訂單隨後會顯示傳送畀邊個同埋幾時傳送，如果內容有更改，你可以再傳送。如果供應商要求你透過佢哋自己嘅網站訂購，請繼續咁樣做 — 從呢度傳送係一種揀，絕唔係鎖定。",
  "training.lessons.mgr-send-supplier-order.title": "將訂單傳送畀供應商",
  "training.lessons.owner-send-supplier-order.step1": "任何已下達嘅採購單都可以從「採購」頁面以電郵傳送畀佢嘅供應商 — 唔令列印，亦唔令另開電郵應用程式。傳送功能位喺「供應商同採購」，屬喺 Business 計劃。",
  "training.lessons.owner-send-supplier-order.step2": "傳送需要供應商記錄上有佢嘅電郵地址。冇地址時，應用程式會坦白拒絕並通知你先新增，而且訂單只有喺電郵真正寄出後，才會被記錄為已傳送。",
  "training.lessons.owner-send-supplier-order.step3": "供應商收到嘅內容只會顯示你嘅商戶名稱 — 你嘅名稱喺電郵上，亦喺隨附嘅訂單 PDF 上；應用程式嘅名稱唔會出現喺佢哋睇到嘅任何地方。",
  "training.lessons.owner-send-supplier-order.step4": "每次傳送都會記錄喺訂單本身上 — 已傳送、幾時、傳送至邊個地址 — 重新傳送會更新記錄。要求透過佢嘅自己網站訂購嘅供應商仍保留該流程；從應用程式傳送絕唔會取代或阻擋該流程。",
  "training.lessons.owner-send-supplier-order.title": "以電郵傳送訂單畀供應商（Business 計劃）",
  "training.lessons.owner-trial-reminders.step1": "喺你自己嘅 7 日試用期間，應用程式會自行提示你 — 兩封電郵寄到你訂閱時使用嘅地址：一封喺試用第 4 日，一封喺試用結束前 24 小時。冇其他電郵，付費計劃永遠唔會收到提示。",
  "training.lessons.owner-trial-reminders.step2": "喺應用程式入面，隨著結束時間接近，三則簡短通知會逐一出現：「你嘅試用仲剩 5 日。」，接住「你嘅試用仲剩 3 日。」，然後「距離試用結束仲剩 24 小時。」試用結束或轉為付費計劃嘅嗰一刻，佢哋就會消失。",
  "training.lessons.owner-trial-reminders.step3": "取消位喺「設定」嘅「帳單」下。如果你喺試用期間取消，你仍可保留完整嘅 7 日 — 而且因為你取消咗，最後一封電郵會改變語氣：佢會坦白通知你唔會有扣款，你嘅計劃就咁樣結束。",
  "training.lessons.owner-trial-reminders.step4": "每封提示電郵只會傳送一次 — 應用程式會保留已傳送內容嘅記錄，因此重新啟動同重複檢查絕唔會令你收到兩次。你試用入面嘅顧客亦會為佢哋自己嘅訂閱收到完全相同嘅提示。",
  "training.lessons.owner-trial-reminders.title": "你嘅試用提示：會收到乜嘢，同埋幾時",
  "settings.delete.cancelFirstHeadline": "刪除前請先取消你嘅訂閱。",
  "settings.delete.cancelFirstBody": "你而家刪除緊你嘅帳戶 — 咁唔代表你取消緊訂閱。請先取消你嘅訂閱，之後隨時喺你準備好嗰陣刪除你嘅帳戶。",
