  "workforce.tab.rewards": "獎勵",
  "training.lessons.mgr-give-rewards.step1": "打開「團隊」，撳「獎勵」。揀團隊成員，然後揀類型：店入面折扣百分比、禮品卡，或用你自己嘅話描述嘅其他內容。",
  "training.lessons.mgr-give-rewards.step2": "為獎勵取一個簡短名稱，如願意可附上備註。對方會即刻收到通知，獎勵會喺佢嘅「我嘅獎勵」中等待，並有自己嘅代碼。",
  "training.lessons.mgr-give-rewards.step3": "依設計嘅界線：你只能獎勵員工。你唔可以獎勵自己或另一位經理 — 獎勵經理係擁有人嘅決定，應用程式會坦白拒絕。",
  "training.lessons.mgr-give-rewards.step4": "喺收銀台，輸入團隊成員向你出示嘅代碼並標示為已使用 — 每個代碼只能使用一次。如果計劃更改，你可以作廢你畀嘅獎勵；擁有人嘅禮物由擁有人作廢。",
  "training.lessons.mgr-give-rewards.title": "畀你嘅員工獎勵",
  "training.lessons.owner-give-rewards.step1": "獎勵位喺「團隊」嘅「獎勵」分頁，且只限 Business 計劃 — 喺 Essentials 計劃下，該分頁會顯示一扇鎖上嘅門，令你嘅團隊可以睇到更大計劃包含嘅內容。",
  "training.lessons.owner-give-rewards.step2": "你可以獎勵團隊入面嘅任何人 — 員工同經理皆可。揀人員，然後揀類型：店入面折扣百分比（任何你揀嘅百分比）、可喺任何地方使用嘅禮品卡，或任何你用自己嘅話描述嘅激勵。",
  "training.lessons.owner-give-rewards.step3": "獎勵會附帶自己嘅一次性代碼送達，並通知對方嘅提示。佢哋喺收銀台出示代碼；擁有人或經理輸入代碼以標示為已使用。",
  "training.lessons.owner-give-rewards.step4": "列印或分享嘅獎勵憑條只會顯示你嘅商戶名稱 — 絕唔會顯示應用程式嘅名稱。呢係你商店嘅感謝，唔係廣告。",
  "training.lessons.owner-give-rewards.title": "畀獎勵（Business 計劃）",
  "training.lessons.owner-rewards-oversight.step1": "你嘅經理亦可以畀獎勵 — 只限員工。應用程式會拒絕經理獎勵自己或另一位經理；獎勵經理永遠係你嘅決定。",
  "training.lessons.owner-rewards-oversight.step2": "你可以喺「獎勵歷史」中睇商戶入面嘅每一個獎勵：邊個畀嘅、邊個收到嘅，同埋佢係可以使用、已使用定係已作廢。經理只能睇到佢哋畀嘅獎勵同佢哋收到嘅獎勵。",
  "training.lessons.owner-rewards-oversight.step3": "你可以作廢任何獎勵，包括你嘅經理畀嘅獎勵。經理可以作廢佢哋自己嘅禮物，但絕唔可以作廢你嘅。",
  "training.lessons.owner-rewards-oversight.step4": "每個代碼只能使用一次，作廢嘅獎勵永遠唔可以使用 — 歷史始終顯示獎勵嘅最終結果。",
  "training.lessons.owner-rewards-oversight.title": "監督獎勵：你經理嘅畀情況",
  "training.lessons.staff-your-rewards.step1": "當你嘅經理或擁有人畀你獎勵時，你嘅提示會響起。打開「團隊」，撳「獎勵」，喺「我嘅獎勵」下睇。",
  "training.lessons.staff-your-rewards.step2": "每個獎勵都有自己嘅代碼。請妥善保管 — 喺收銀台出示代碼嘅人就係使用該獎勵嘅人。",
  "training.lessons.staff-your-rewards.step3": "若要使用，請喺購買時出示代碼。收銀台嘅人員會輸入代碼並標示為已使用 — 每個代碼只能使用一次。",
  "training.lessons.staff-your-rewards.step4": "獎勵係 Business 計劃嘅福利。如果你嘅商店未使用 Business 計劃，「獎勵」分頁會改為顯示一扇鎖上嘅門 — 嗰係計劃嘅安排，唔係錯誤。",
  "training.lessons.staff-your-rewards.title": "你嘅獎勵：搵到你嘅代碼並使用佢",
