  "pos.title": "收銀台連接",
  "pos.webhookPending": "我哋呢邊嘅銷售 webhooks 仲未打開 — 連接已儲存，銷售會喺打開嘅嗰一刻開始送達。",
  "training.lessons.owner-pos-connect-shopify.step1": "收銀台連接係 Business 計劃嘅一部分。Shopify POS 銷售就係 Shopify 訂單，因此連接係依商店進行嘅：喺 Shopify 入面，為你嘅商店建立一個自訂應用程式並複製佢嘅存取權杖。喺「收銀台連接」頁面上，貼上你嘅商店網域（例如 your-store.myshopify.com）同權杖。",
  "training.lessons.owner-pos-connect-shopify.step2": "權杖只儲存在伺服器上 — 佢絕唔會再顯示出嚟，連你亦睇唔到。如果你第日貼上一個新權杖，佢會直接取代舊嘅。",
  "training.lessons.owner-pos-connect-shopify.step3": "如果你有多個地點，請揀此商店嘅銷售要從邊個地點扣除。然後每筆訂單 — 無論係喺 Shopify 收銀台定係線上 — 都會自動從呢度嘅庫存中扣除佢嘅產品。",
  "training.lessons.owner-pos-connect-shopify.step4": "一間商店喺呢度連接到一個工作區。如果某個網域已喺其他地方連接，應用程式會坦白講明，而唔會共用佢。",
  "training.lessons.owner-pos-connect-shopify.title": "連接 Shopify POS",
  "training.lessons.owner-pos-connect-square.step1": "收銀台連接係 Business 計劃嘅一部分。打開「收銀台連接」（喺「銷售」選單中），撳 Square 卡片上嘅「連接」。你會前往 Square 自己嘅頁面批准連接 — 應用程式絕唔會睇到你嘅 Square 密碼。",
  "training.lessons.owner-pos-connect-square.step2": "返到應用程式後，卡片會顯示「已連接」。如果你嘅商店有多個地點，請揀此收銀台嘅銷售要從邊個地點扣除；否則銷售會從你嘅第一個地點扣除。",
  "training.lessons.owner-pos-connect-square.step3": "從此以後，每筆 Square 銷售都會自動從呢度嘅庫存中扣除產品。喺收銀台售出一件產品，然後睇同一個頁面上嘅「最近銷售」清單：銷售會喺片刻入面送達，並標示為已計算。",
  "training.lessons.owner-pos-connect-square.step4": "一筆銷售絕唔會計算兩次 — 如果 Square 再傳送同一筆銷售，應用程式會認出佢同埋唔作任何更改。中斷連接喺同一張卡片上，佢會即刻停止對應。",
  "training.lessons.owner-pos-connect-square.title": "連接 Square：為你移動庫存嘅銷售",
  "training.lessons.owner-pos-csv.step1": "任何可以匯出銷售檔案嘅收銀台仍然可以為你嘅庫存提供資料。將當天嘅銷售匯出為 CSV，欄位如下：sale_id、sold_at、sku_or_barcode、quantity — item_name 同 location 有幫助，不過係可唔填嘅。",
  "training.lessons.owner-pos-csv.step2": "喺「收銀台連接」頁面上上傳檔案。每個 sale_id 只會記錄一次：明天再上傳同一個檔案唔會有任何更改，佢只會報告重複項目。",
  "training.lessons.owner-pos-csv.step3": "應用程式唔可以使用嘅資料行絕唔會被靜靜雞跳過 — 冇 sale_id 嘅資料行，或數量唔係數字嘅資料行，會連同佢嘅行號同原因一齊列出畀你。",
  "training.lessons.owner-pos-csv.step4": "產品依 SKU 或條碼對應，同即時收銀台完全相同。任何未對應嘅項目都會喺對應畫面上等待，同其他銷售相同。",
  "training.lessons.owner-pos-csv.title": "冇收銀台 API？使用日終 CSV",
  "training.lessons.owner-pos-mapping.step1": "收銀台產品依 SKU 或條碼同你嘅產品對應。當一筆銷售送達時，附帶應用程式從未見過嘅產品，該產品會被暫緩 — 庫存唔會移動，銷售會喺「收銀台連接」頁面嘅「等待對應嘅產品」下等待。",
  "training.lessons.owner-pos-mapping.step2": "揀該產品實際上係你嘅邊個產品，然後儲存。該對應會被永久記住：該產品嘅每一筆將來銷售都會自行計算。",
  "training.lessons.owner-pos-mapping.step3": "儲存後，撳「套用到暫緩銷售」以計算等待入面嘅銷售 — 佢哋會喺當下寫入佢嘅庫存異動，並附上銷售自己嘅參照。",
  "training.lessons.owner-pos-mapping.step4": "如果暫緩嘅銷售要求嘅數量超過貨架上嘅數量，佢會保持標示為庫存唔足，而唔係令數量變成負數。補貨後，再從同一個畫面套用一次。",
  "training.lessons.owner-pos-mapping.title": "當收銀台產品唔可以對應時：對應畫面",
  "training.lessons.owner-pos-sales-list.step1": "「收銀台連接」頁面上嘅「最近銷售」清單會顯示你嘅收銀台傳送嘅每一筆銷售：邊個收銀台、銷售編號、幾時、收銀台報告嘅總額，同埋每件產品嘅處理結果。",
  "training.lessons.owner-pos-sales-list.step2": "「已計算」表示庫存已移動。「部分已計算」表示有啲產品已計算，有啲而家等待或短缺 — 打開銷售以淺白文字睇係邊一個。",
  "training.lessons.owner-pos-sales-list.step3": "「已暫緩」表示該銷售中仲未有任何產品被計算：某個產品需要對應（請參閱對應課程）、貨架數量唔足，或銷售喺商店未使用 Business 計劃時送達。呢三種情況都可以從同一個頁面修正 — 因計劃而暫緩嘅銷售，一旦商店返到 Business 計劃，就可以從呢度計算 — 而且任何內容都絕唔會靜靜雞遺失。",
  "training.lessons.owner-pos-sales-list.step4": "每筆已計算嘅銷售都會喺你嘅庫存歷史中寫入一筆正常嘅「已售出」記錄，並附上指明收銀台同銷售嘅參照 — 因此你嘅「異動記錄」頁面同你嘅收銀台始終講述同一個故事。",
  "training.lessons.owner-pos-sales-list.title": "睇你嘅收銀台銷售",
  "training.lessons.staff-pos-till-sales.step1": "如果你嘅商店使用 Business 計劃並已連接佢嘅收銀台（Square 或 Shopify POS），收銀機嘅每筆銷售都會自動從呢度嘅庫存中扣除該產品 — 唔令掃描出庫，亦唔令稍後手動輸入。",
  "training.lessons.staff-pos-till-sales.step2": "你可以喺「收銀台連接」頁面上即時觀睇：每筆銷售都會顯示售出咗乜嘢、數量幾多，同埋係唔係已計算。已計算嘅銷售會以淺白文字顯示為已計算。",
  "training.lessons.staff-pos-till-sales.step3": "有時銷售會改為被暫緩：收銀台售出咗應用程式仲未有法對應到產品嘅物品。庫存冇被扣除 — 銷售會等待，直到擁有人或經理喺對應畫面上將該產品對應一次。之後，佢就會被計算，同一產品嘅下一筆銷售亦會自行對應。",
  "training.lessons.staff-pos-till-sales.step4": "如果暫緩嘅銷售同你剛售出嘅產品有關，請告知你嘅經理或擁有人 — 一次快速對應就能永久修正。絕唔要手動調整庫存來彌補暫緩嘅銷售；一旦對應完成，嗰樣會計算兩次。",
  "training.lessons.staff-pos-till-sales.title": "當收銀台售出時，你嘅庫存會自行移動",
