  "plansLib.includes.support": "應用程式入面問題回報",
  "support.category.broken": "有嘢壞咗",
  "support.category.idea": "想法或建議",
  "support.category.looksWrong": "有嘢睇落唔對",
  "support.category.other": "其他",
  "support.categoryLabel": "呢係關喺乜嘢嘅？",
  "support.contextNote": "為咗令我哋搵到問題，你嘅備註會自動包含你身處嘅頁面、你嘅商戶同角色（如已揀）、你嘅計劃、你嘅應用程式語言，同埋你使用嘅手機或瀏覽器類型。佢絕唔會包含你嘅產品、庫存或銷售。",
  "support.description": "有嘢壞咗、有嘢睇落唔對，或有想法要分享嗎？請喺呢度通知我哋 — 你嘅備註會直接送交應用程式背後嘅團隊。",
  "support.errorGeneric": "操作未成功。請再試一次。",
  "support.errorRateLimit": "你今日已傳送咗幾份報告 — 謝謝你。請等到明天再傳送更多，令每份報告都能被妥善睇。",
  "support.errorTooLong": "內容比報告可容納嘅長度仲長 — 請稍微刪減後再傳送一次。",
  "support.errorTooShort": "請多通知我哋一點 — 一兩句話有助我哋搵到問題。",
  "support.messageLabel": "發生咗乜嘢事？",
  "support.messagePlaceholder": "用你自己嘅話通知我哋你當時喺做乜嘢，同埋邊度出錯咗…",
  "support.sendAnother": "傳送另一份報告",
  "support.sending": "傳送緊…",
  "support.sentBody": "我哋會睇每份報告。如果我哋需要更多詳細資料，我哋會寫信到你嘅帳號電郵。",
  "support.sentTitle": "謝謝你 — 你嘅報告已傳送。",
  "support.submit": "傳送報告",
  "support.title": "回報問題",
  "support.urgentNote": "反而係入唔到自己帳戶？備用密鑰可以幫你入返去 — 睇下上面嘅「安全同備用密鑰」，或者用登入頁面嘅恢復入口。",
  "training.lessons.mgr-report-problem.step1": "你嘅團隊喺收銀台工作，嗰度最先出現問題。如果應用程式為你團隊入面嘅任何人故障或行為異常，可以喺當下從「設定」嘅「回報問題」回報 — 由佢哋或由你回報皆可。",
  "training.lessons.mgr-report-problem.step2": "請要求淺白嘅故事：佢哋當時喺做乜嘢、佢哋預期乜嘢、實際發生咗乜嘢。咁樣嘅一兩句話，勝過事後寫出嘅完美描述。",
  "training.lessons.mgr-report-problem.step3": "報告會自行附上頁面、商店、傳送者嘅角色、計劃、應用程式語言同裝置類型；產品、庫存同銷售絕唔會附上。商店嘅數字唔會隨報告一齊離開。",
  "training.lessons.mgr-report-problem.step4": "報告會送交應用程式背後嘅團隊，每一份都會被睇。如果問題將某人鎖喺帳號外面，唔要等報告：備用密鑰同登入頁面嘅恢復入口可以令佢哋返嚟。",
  "training.lessons.mgr-report-problem.title": "當你嘅團隊遇到問題時：回報佢，唔要繞過佢",
  "training.lessons.owner-report-problem.step1": "你嘅訂閱包含一條直達應用程式開發者嘅專線。打開「設定」，使用「回報問題」 — 佢喺每個計劃下皆可使用，供你同你團隊嘅每位成員使用。",
  "training.lessons.owner-report-problem.step2": "用你自己嘅話講明發生咗乜嘢事：你當時想做乜嘢，同埋應用程式實際做咗乜嘢。表格會自行附上修正所需嘅詳細資料 — 頁面、商戶、角色、計劃、語言同裝置；你嘅產品、庫存同銷售絕唔會包含喺入面。",
  "training.lessons.owner-report-problem.step3": "每份報告都會被儲存並由團隊睇。如果更多詳細資料有幫助，佢哋會回覆傳送者嘅帳號電郵 — 因此答案會送達睇到問題嘅人。",
  "training.lessons.owner-report-problem.step4": "一個例外：如果你或團隊成員完全唔可以進入帳號，報告唔係最快嘅入口。備用密鑰（設定，安全性同備用密鑰）同登入頁面上嘅恢復入口正係為此而設。",
  "training.lessons.owner-report-problem.title": "回報問題：你直達應用程式團隊嘅專線",
  "training.lessons.report-problem.step1": "如果應用程式中有嘢壞咗、睇落唔對，或感覺唔對勁，你唔令忍受佢。打開「設定」，搵到「回報問題」 — 佢供每個人喺每個計劃下使用。",
  "training.lessons.report-problem.step2": "揀你嘅備註係關喺乜嘢嘅 — 有嘢壞咗、有嘢睇落唔對、一個想法，或其他 — 然後用你自己嘅話寫下發生咗乜嘢事。你當時喺做乜嘢最有幫助。",
  "training.lessons.report-problem.step3": "你嘅備註會自動附帶你身處嘅頁面、你嘅商店同角色、你嘅計劃、你嘅應用程式語言，同埋你使用嘅手機或瀏覽器類型 — 呢啲詳細資料有助搵到問題。佢絕唔會附帶你嘅產品、庫存或銷售。",
  "training.lessons.report-problem.step4": "傳送佢，佢會直接送交應用程式背後嘅團隊，佢哋會睇每份報告。如果佢哋需要更多詳細資料，佢哋會寫信到你嘅帳號電郵。反而係入唔到自己帳戶？請使用你嘅備用密鑰或登入頁面上嘅恢復入口 — 嗰啲比報告更快。",
  "training.lessons.report-problem.title": "回報問題：當有嘢壞掉時通知我哋",
  "crossStore.transferButton": "搬貨",
