  "crossStore.transferIntro": "兩間舖都係你嘅，所以你可以直接搬貨，唔使申請。揀一個產品，講低幾多同埋由邊度出發，再揀佢去到邊間舖。兩間舖都會即刻更新，而且兩邊都會留低今次搬貨嘅記錄。",
  "crossStore.transferNoTargets": "你仲未有另一間屬於你嘅舖——貨只可以喺屬於你嘅舖之間搬嚟搬去。",
