  "crossStore.transferTitle": "將貨搬去另一間舖",
  "crossStore.transferToFirstLocation": "佢嘅第一個位置",
  "crossStore.transferToLocation": "去邊個位置",
  "training.lessons.owner-move-stock.step1": "申請係用嚟請求嘅；搬貨係老闆嘅事。喺跨店收件箱頁面，「搬貨」面板畀你——老闆——直接將貨由呢間舖送去你擁有嘅另一間舖，唔使申請，亦唔使等。",
  "training.lessons.owner-move-stock.step2": "揀產品、佢出發嘅位置同數量。個應用程式會顯示嗰個位置現有幾多貨，一次搬貨絕對唔可以多過呢個數量。",
  "training.lessons.owner-move-stock.step3": "揀目標舖頭，如果想，仲可以揀嗰度嘅確切位置。如果嗰間舖已經有相同嘅 SKU，啲貨會併入嗰個產品；如果冇，產品會連埋啲貨一齊複製過去。",
  "training.lessons.owner-move-stock.step4": "兩間舖都會留低記錄：呢間舖顯示轉出，另一間顯示接收。如果搬唔到貨——唔夠貨，或者另一間舖唔係你嘅——就乜都唔會搬，個應用程式會講明原因。",
  "training.lessons.owner-move-stock.title": "喺你自己嘅舖之間搬貨（Business 計劃）",
